const Parse = require('parse/node').Parse;
const mongodb = require('mongodb');

const {
  transformKey,
  parseObjectToMongoObjectForCreate,
  transformUpdate,
  transformWhere,
  mongoObjectToParseObject,
  transformConstraint,
  transformPointerString,
} = require('../../../../src/Adapters/Storage/Mongo/MongoTransform');

const schemaWith = fields => ({ fields });

function expectParseError(fn, code, message) {
  let error;
  try {
    fn();
  } catch (caught) {
    error = caught;
  }
  expect(error).toBeInstanceOf(Parse.Error);
  expect(error.code).toBe(code);
  if (message instanceof RegExp) {
    expect(error.message).toMatch(message);
  } else if (message !== undefined) {
    expect(error.message).toBe(message);
  }
}

describe('transformKey', () => {
  test.each([
    ['objectId', '_id'],
    ['createdAt', '_created_at'],
    ['updatedAt', '_updated_at'],
    ['sessionToken', '_session_token'],
    ['lastUsed', '_last_used'],
    ['timesUsed', 'times_used'],
  ])('maps the built-in field %s to %s', (fieldName, mongoFieldName) => {
    expect(transformKey('Anything', fieldName, schemaWith({}))).toBe(mongoFieldName);
  });

  test('leaves ordinary field names unchanged', () => {
    expect(transformKey('Game', 'score', schemaWith({ score: { type: 'Number' } }))).toBe('score');
  });

  test('prefixes pointer fields declared with the current schema format', () => {
    const schema = schemaWith({ owner: { type: 'Pointer', targetClass: '_User' } });
    expect(transformKey('Game', 'owner', schema)).toBe('_p_owner');
  });

  test('prefixes pointer fields declared with the legacy __type schema format', () => {
    const schema = schemaWith({ owner: { __type: 'Pointer', className: '_User' } });
    expect(transformKey('Game', 'owner', schema)).toBe('_p_owner');
  });

  test('built-in names win over pointer declarations', () => {
    const schema = schemaWith({ createdAt: { type: 'Pointer', targetClass: 'Thing' } });
    expect(transformKey('Game', 'createdAt', schema)).toBe('_created_at');
  });
});

describe('transformPointerString', () => {
  const schema = schemaWith({ owner: { type: 'Pointer', targetClass: '_User' } });

  test('converts a stored pointer string into REST pointer format', () => {
    expect(transformPointerString(schema, 'owner', '_User$abc123')).toEqual({
      __type: 'Pointer',
      className: '_User',
      objectId: 'abc123',
    });
  });

  test('rejects a pointer whose class does not match the schema', () => {
    expect(() => transformPointerString(schema, 'owner', 'Game$abc123')).toThrow(
      'pointer to incorrect className'
    );
  });
});

describe('transformWhere', () => {
  const schema = schemaWith({
    owner: { type: 'Pointer', targetClass: '_User' },
    tags: { type: 'Array' },
    score: { type: 'Number' },
    when: { type: 'Date' },
  });

  test('maps built-in fields, dates, and ordinary atom values', () => {
    const created = new Date('2024-01-02T03:04:05.678Z');
    const updated = new Date('2024-02-03T04:05:06.789Z');

    expect(
      transformWhere(
        '_User',
        {
          objectId: 'user-1',
          createdAt: '2024-01-02T03:04:05.678Z',
          updatedAt: updated,
          sessionToken: 'token',
          lastUsed: '2024-03-04T05:06:07.890Z',
          timesUsed: 3,
          _rperm: ['role:admin'],
          username: 'alice',
        },
        schema
      )
    ).toEqual({
      _id: 'user-1',
      _created_at: created,
      _updated_at: updated,
      _session_token: 'token',
      _last_used: new Date('2024-03-04T05:06:07.890Z'),
      times_used: 3,
      _rperm: ['role:admin'],
      username: 'alice',
    });
  });

  test('maps auxiliary auth expiration fields to dates', () => {
    const result = transformWhere(
      '_User',
      {
        expiresAt: '2024-05-01T00:00:00.000Z',
        _email_verify_token_expires_at: '2024-05-02T00:00:00.000Z',
        _account_lockout_expires_at: '2024-05-03T00:00:00.000Z',
        _perishable_token_expires_at: '2024-05-04T00:00:00.000Z',
        _password_changed_at: '2024-05-05T00:00:00.000Z',
      },
      schemaWith({})
    );

    expect(result).toEqual({
      expiresAt: new Date('2024-05-01T00:00:00.000Z'),
      _email_verify_token_expires_at: new Date('2024-05-02T00:00:00.000Z'),
      _account_lockout_expires_at: new Date('2024-05-03T00:00:00.000Z'),
      _perishable_token_expires_at: new Date('2024-05-04T00:00:00.000Z'),
      _password_changed_at: new Date('2024-05-05T00:00:00.000Z'),
    });
  });

  test('coerces objectId for global configuration classes', () => {
    expect(transformWhere('_GlobalConfig', { objectId: '42' }, schemaWith({}))).toEqual({
      _id: 42,
    });
    expect(transformWhere('_GraphQLConfig', { objectId: '7' }, schemaWith({}))).toEqual({
      _id: 7,
    });
    expect(transformWhere('Game', { objectId: '42' }, schemaWith({}))).toEqual({ _id: '42' });
  });

  test('turns pointer constraints into class$objectId strings and prefixes the field', () => {
    expect(
      transformWhere(
        'Game',
        { owner: { __type: 'Pointer', className: '_User', objectId: 'u-1' } },
        schema
      )
    ).toEqual({ _p_owner: '_User$u-1' });
  });

  test('wraps a scalar comparison for an array field in $all', () => {
    expect(transformWhere('Game', { tags: 'featured' }, schema)).toEqual({
      tags: { $all: ['featured'] },
    });
  });

  test('supports comparison and existence constraints', () => {
    expect(
      transformWhere('Game', { score: { $gt: 10, $gte: 11, $lt: 20, $lte: 19, $ne: 15 } }, schema)
    ).toEqual({
      score: { $gt: 10, $gte: 11, $lt: 20, $lte: 19, $ne: 15 },
    });
    expect(transformWhere('Game', { score: { $exists: false } }, schema)).toEqual({
      score: { $exists: false },
    });
  });

  test('flattens nested arrays in $in and $nin constraints', () => {
    expect(
      transformWhere('Game', { score: { $in: [1, [2, 3]], $nin: [4, [5]] } }, schema)
    ).toEqual({
      score: { $in: [1, 2, 3], $nin: [4, 5] },
    });
  });

  test('rejects non-array $in and $nin values', () => {
    expectParseError(
      () => transformWhere('Game', { score: { $in: 4 } }, schema),
      Parse.Error.INVALID_JSON,
      'bad $in value'
    );
    expectParseError(
      () => transformWhere('Game', { score: { $nin: '4' } }, schema),
      Parse.Error.INVALID_JSON,
      'bad $nin value'
    );
  });

  test('transforms REST date atoms inside $all', () => {
    const iso = '2024-06-01T12:00:00.000Z';
    expect(
      transformWhere(
        'Game',
