        schema
      )
    ).toEqual({
      tags: { $all: ['a', new Date(iso)] },
    });
  });

  test('recursively transforms $or, $and, and $nor subqueries', () => {
    expect(
      transformWhere(
        'Game',
        {
          $or: [{ objectId: 'a' }, { score: { $gt: 1 } }],
          $and: [{ owner: { __type: 'Pointer', className: '_User', objectId: 'u' } }],
          $nor: [{ createdAt: '2024-01-01T00:00:00.000Z' }],
        },
        schema
      )
    ).toEqual({
      $or: [{ _id: 'a' }, { score: { $gt: 1 } }],
      $and: [{ _p_owner: '_User$u' }],
      $nor: [{ _created_at: new Date('2024-01-01T00:00:00.000Z') }],
    });
  });

  test('maps authData paths for _User queries', () => {
    expect(
      transformWhere(
        '_User',
        {
          'authData.facebook.id': 'fb-1',
          'authData.google': { id: 'g-1' },
        },
        schemaWith({})
      )
    ).toEqual({
      '_auth_data_facebook.id': 'fb-1',
      _auth_data_google: { id: 'g-1' },
    });
  });

  test('rejects an unsupported plain-object query value', () => {
    expectParseError(
      () => transformWhere('Game', { profile: { nickname: 'ace' } }, schema),
      Parse.Error.INVALID_JSON,
      /You cannot use .* as a query parameter/
    );
  });
});

describe('transformConstraint', () => {
  test('supports $regex and $options', () => {
    expect(transformConstraint({ $regex: '^a', $options: 'i' }, { type: 'String' }, 'name')).toEqual({
      $regex: '^a',
      $options: 'i',
    });
  });

  test('rejects a non-string $regex value', () => {
    expectParseError(
      () => transformConstraint({ $regex: /a/ }, { type: 'String' }, 'name'),
      Parse.Error.INVALID_JSON,
      /bad regex:/
    );
  });

  test('converts $containedBy into an $elemMatch/$nin expression', () => {
    expect(
      transformConstraint({ $containedBy: ['a', 'b'] }, { type: 'Array' }, 'tags')
    ).toEqual({
      $elemMatch: { $nin: ['a', 'b'] },
    });
  });

  test('rejects a non-array $containedBy value', () => {
    expectParseError(
      () => transformConstraint({ $containedBy: 'a' }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      'bad $containedBy: should be an array'
    );
  });

  test('accepts a uniform set of StartsWith regexes in $all', () => {
    const result = transformConstraint(
      { $all: [{ $regex: '^\\Qfoo\\E' }, { $regex: '^\\Qbar\\E' }] },
      { type: 'Array' },
      'tags'
    );
    expect(result.$all).toHaveLength(2);
    expect(result.$all[0]).toBeInstanceOf(RegExp);
    expect(result.$all[1]).toBeInstanceOf(RegExp);
    expect(result.$all[0].toString()).toBe('/^\\Qfoo\\E/');
    expect(result.$all[1].toString()).toBe('/^\\Qbar\\E/');
  });

  test('rejects a mixture of regex and non-regex values in $all', () => {
    expectParseError(
      () => transformConstraint({ $all: [{ $regex: '^\\Qfoo\\E' }, 'plain'] }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      /All \$all values must be of regex type or none/
    );
  });

  test('rejects a non-array $all value', () => {
    expectParseError(
      () => transformConstraint({ $all: 'a' }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      'bad $all value'
    );
  });

  test('translates full text search options', () => {
    expect(
      transformConstraint(
        {
          $text: {
            $search: {
              $term: 'space station',
              $language: 'en',
              $caseSensitive: true,
              $diacriticSensitive: false,
            },
          },
        },
        undefined,
        'name'
      )
    ).toEqual({
      $text: {
        $search: 'space station',
        $language: 'en',
        $caseSensitive: true,
      },
    });
  });

  test('validates $text options', () => {
    expectParseError(
      () => transformConstraint({ $text: { $search: 'not-an-object' } }, undefined, 'name'),
      Parse.Error.INVALID_JSON,
      'bad $text: $search, should be object'
    );
    expectParseError(
      () => transformConstraint({ $text: { $search: {} } }, undefined, 'name'),
      Parse.Error.INVALID_JSON,
      'bad $text: $term, should be string'
    );
    expectParseError(
      () => transformConstraint({ $text: { $search: { $term: 'x', $language: 4 } } }, undefined, 'name'),
      Parse.Error.INVALID_JSON,
      'bad $text: $language, should be string'
    );
  });

  test('translates $nearSphere normally', () => {
    expect(
      transformConstraint(
        { $nearSphere: { longitude: 10, latitude: 20 }, $maxDistance: 5 },
        undefined,
        'location'
      )
    ).toEqual({
      $nearSphere: [10, 20],
      $maxDistance: 5,
    });
  });

  test('translates $nearSphere to $geoWithin for count queries', () => {
    expect(
      transformConstraint(
        { $nearSphere: { longitude: 10, latitude: 20 }, $maxDistance: 5 },
        undefined,
        'location',
        true
      )
    ).toEqual({
      $geoWithin: { $centerSphere: [[10, 20], 5] },
    });
  });

  test('translates alternative distance units to radians', () => {
    expect(transformConstraint({ $maxDistanceInRadians: 2 }, undefined, 'location')).toEqual({
      $maxDistance: 2,
    });
    expect(transformConstraint({ $maxDistanceInMiles: 3959 }, undefined, 'location')).toEqual({
      $maxDistance: 1,
    });
    expect(transformConstraint({ $maxDistanceInKilometers: 6371 }, undefined, 'location')).toEqual({
      $maxDistance: 1,
    });
  });

  test('converts a $within box from GeoPoint order to longitude/latitude order', () => {
    expect(
      transformConstraint(
        {
          $within: {
            $box: [
              { longitude: 1, latitude: 2 },
              { longitude: 3, latitude: 4 },
            ],
          },
        },
        undefined,
        'location'
      )
    ).toEqual({ $within: { $box: [[1, 2], [3, 4]] } });
  });

  test('rejects malformed $within boxes', () => {
    expectParseError(
      () => transformConstraint({ $within: { $box: [{ longitude: 1, latitude: 2 }] } }, undefined, 'location'),
      Parse.Error.INVALID_JSON,
      'malformatted $within arg'
    );
  });

  test('converts $geoWithin polygons of GeoPoints', () => {
    expect(
      transformConstraint(
        {
          $geoWithin: {
            $polygon: [
              { __type: 'GeoPoint', longitude: 10, latitude: 20 },
              { __type: 'GeoPoint', longitude: 30, latitude: 40 },
              { __type: 'GeoPoint', longitude: 50, latitude: 60 },
            ],
          },
        },
        undefined,
        'location'
      )
    ).toEqual({ $geoWithin: { $polygon: [[10, 20], [30, 40], [50, 60]] } });
  });

  test('converts $geoWithin centerSphere expressions', () => {
    expect(
      transformConstraint(
        {
          $geoWithin: {
            $centerSphere: [{ __type: 'GeoPoint', longitude: 10, latitude: 20 }, 2.5],
          },
        },
        undefined,
        'location'
      )
    ).toEqual({ $geoWithin: { $centerSphere: [[10, 20], 2.5] } });
  });

  test('validates $geoWithin polygons and centerSphere distances', () => {
    expectParseError(
      () =>
        transformConstraint(
          {
            $geoWithin: {
              $polygon: [
                { __type: 'GeoPoint', longitude: 1, latitude: 2 },
                { __type: 'GeoPoint', longitude: 3, latitude: 4 },
              ],
            },
          },
          undefined,
          'location'
        ),
      Parse.Error.INVALID_JSON,
      'bad $geoWithin value; $polygon should contain at least 3 GeoPoints'
    );

    expectParseError(
      () =>
        transformConstraint(
          {
            $geoWithin: {
              $centerSphere: [{ __type: 'GeoPoint', longitude: 1, latitude: 2 }, -1],
            },
          },
          undefined,
          'location'
        ),
      Parse.Error.INVALID_JSON,
      'bad $geoWithin value; $centerSphere distance invalid'
    );
  });

  test('converts $geoIntersects points to GeoJSON', () => {
    expect(
      transformConstraint(
        {
          $geoIntersects: {
            $point: { __type: 'GeoPoint', longitude: 10, latitude: 20 },
          },
        },
        undefined,
        'location'
      )
    ).toEqual({
      $geoIntersects: { $geometry: { type: 'Point', coordinates: [10, 20] } },
    });
  });

  test('rejects unsupported select constraints and unknown $ constraints', () => {
    expectParseError(
      () => transformConstraint({ $select: {} }, undefined, 'owner'),
      Parse.Error.COMMAND_UNAVAILABLE,
      'the $select constraint is not supported yet'
    );
    expectParseError(
      () => transformConstraint({ $dontSelect: {} }, undefined, 'owner'),
      Parse.Error.COMMAND_UNAVAILABLE,
      'the $dontSelect constraint is not supported yet'
    );
    expectParseError(
      () => transformConstraint({ $unknown: 1 }, undefined, 'field'),
      Parse.Error.INVALID_JSON,
      'bad constraint: $unknown'
    );
  });

  test('returns CannotTransform-like value for non-constraint objects', () => {
    // The helper's sentinel is not exported, so observe the conversion through
    // an exported caller: a plain equality atom is handled by transformWhere.
    expect(transformWhere('Game', { name: 'alice' }, schemaWith({ name: { type: 'String' } }))).toEqual({
      name: 'alice',
    });
  });

  test('evaluates relative dates against the current time for $gt/$gte', () => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
    try {
      expect(
        transformConstraint(
          {
            $gt: { $relativeTime: 'in 2 days' },
            $lte: { $relativeTime: '3 hours ago' },
          },
          { type: 'Date' },
          'when'
        )
      ).toEqual({
        $gt: new Date('2024-01-03T00:00:00.000Z'),
        $lte: new Date('2023-12-31T21:00:00.000Z'),
      });
    } finally {
      jest.useRealTimers();
    }
  });

  test('validates relative-time fields, operators, and expressions', () => {
    expectParseError(
      () =>
        transformConstraint(
          { $gt: { $relativeTime: 'in 1 day' } },
          { type: 'String' },
          'field'
        ),
      Parse.Error.INVALID_JSON,
      '$relativeTime can only be used with Date field'
    );

    expectParseError(
      () =>
        transformConstraint(
          { $eq: { $relativeTime: 'in 1 day' } },
          { type: 'Date' },
          'when'
        ),
      Parse.Error.INVALID_JSON,
      '$relativeTime can only be used with the $lt, $lte, $gt, and $gte operators'
    );

    expectParseError(
      () =>
        transformConstraint(
          { $gt: { $relativeTime: 'tomorrow' } },
          { type: 'Date' },
          'when'
        ),
      Parse.Error.INVALID_JSON,
      /bad \$relativeTime \(\$gt\) value/
    );
  });
});

describe('parseObjectToMongoObjectForCreate', () => {
  const schema = schemaWith({
    owner: { type: 'Pointer', targetClass: '_User' },
    score: { type: 'Number' },
    tags: { type: 'Array' },
    profile: { type: 'Object' },
    friend: { type: 'Relation', targetClass: '_User' },
  });

  test('creates a Mongo object from ordinary fields and built-ins', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        '_User',
        {
          objectId: 'user-1',
          username: 'alice',
          sessionToken: 'sess',
          score: 12,
          _failed_login_count: 2,
          _hashed_password: 'hash',
        },
        schema
      )
    ).toEqual({
      _id: 'user-1',
      username: 'alice',
      _session_token: 'sess',
      score: 12,
      _failed_login_count: 2,
      _hashed_password: 'hash',
    });
  });

  test('uses legacy Mongo names for createdAt and updatedAt', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        'Game',
        {
          createdAt: '2024-01-02T03:04:05.678Z',
          updatedAt: { __type: 'Date', iso: '2024-02-03T04:05:06.789Z' },
        },
        schema
      )
    ).toEqual({
      _created_at: new Date('2024-01-02T03:04:05.678Z'),
      _updated_at: new Date('2024-02-03T04:05:06.789Z'),
    });
  });

  test('coerces auth expiration fields to dates', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        '_User',
        {
          expiresAt: '2024-05-01T00:00:00.000Z',
          _email_verify_token_expires_at: { __type: 'Date', iso: '2024-05-02T00:00:00.000Z' },
          _account_lockout_expires_at: '2024-05-03T00:00:00.000Z',
          _perishable_token_expires_at: '2024-05-04T00:00:00.000Z',
          _password_changed_at: '2024-05-05T00:00:00.000Z',
        },
        schema
      )
    ).toEqual({
      expiresAt: new Date('2024-05-01T00:00:00.000Z'),
      _email_verify_token_expires_at: new Date('2024-05-02T00:00:00.000Z'),
      _account_lockout_expires_at: new Date('2024-05-03T00:00:00.000Z'),
      _perishable_token_expires_at: new Date('2024-05-04T00:00:00.000Z'),
      _password_changed_at: new Date('2024-05-05T00:00:00.000Z'),
    });
  });

  test('prefixes pointer values and recursively transforms arrays and nested objects', () => {
    const iso = '2024-03-04T05:06:07.890Z';
    const result = parseObjectToMongoObjectForCreate(
      'Game',
      {
        owner: { __type: 'Pointer', className: '_User', objectId: 'u-1', extra: 'discarded' },
        tags: ['a', { __type: 'Date', iso }],
        profile: {
          friend: { __type: 'Pointer', className: '_User', objectId: 'u-2', extra: 'discarded' },
          nested: { value: 7 },
        },
      },
      schema
    );

    expect(result).toEqual({
      _p_owner: '_User$u-1',
      tags: ['a', new Date(iso)],
      profile: {
        friend: { __type: 'Pointer', className: '_User', objectId: 'u-2' },
        nested: { value: 7 },
      },
    });
  });

  test('converts REST value coders while creating objects', () => {
    const result = parseObjectToMongoObjectForCreate(
      'Game',
      {
        when: { __type: 'Date', iso: '2024-01-01T00:00:00.000Z' },
        data: { __type: 'Bytes', base64: 'aGVsbG8=' },
        location: { __type: 'GeoPoint', latitude: 20, longitude: 10 },
        shape: {
          __type: 'Polygon',
          coordinates: [
            [10, 20],
            [30, 40],
            [50, 60],
          ],
        },
        attachment: { __type: 'File', name: 'hello.txt' },
      },
      schema
    );

    expect(result.when).toEqual(new Date('2024-01-01T00:00:00.000Z'));
    expect(result.data).toBeInstanceOf(mongodb.Binary);
    expect(result.data.buffer.toString('base64')).toBe('aGVsbG8=');
    expect(result.location).toEqual([10, 20]);
    expect(result.shape).toEqual({
      type: 'Polygon',
      coordinates: [[[20, 10], [40, 30], [60, 50], [20, 10]]],
    });
    expect(result.attachment).toBe('hello.txt');
  });

  test('adds the legacy ACL representation without mutating the input', () => {
    const rest = { _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] };
    expect(parseObjectToMongoObjectForCreate('Game', rest, schema)).toEqual({
      _wperm: ['role:admin', 'user-1'],
      _rperm: ['user-1', '*'],
      _acl: {
        'role:admin': { w: true },
        'user-1': { w: true, r: true },
        '*': { r: true },
      },
    });
    expect(rest).toEqual({ _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] });
  });

  test('skips relations and undefined values', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        'Game',
        {
          friend: { __type: 'Relation', className: '_User' },
          name: undefined,
          score: 0,
        },
        schema
      )
    ).toEqual({ score: 0 });
  });

  test('rejects nested keys containing $ or .', () => {
    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          'Game',
          { profile: { 'bad.key': 1 } },
          schema
        ),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );

    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          'Game',
          { profile: { '$bad': 1 } },
          schema
        ),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );
  });

  test('rejects an untransformed ACL field', () => {
    expect(() =>
      parseObjectToMongoObjectForCreate('Game', { ACL: { 'user-1': { read: true } } }, schema)
    ).toThrow('There was a problem transforming an ACL.');
  });

