describe('transformConstraint', () => {
  test('supports $regex and $options', () => {
    expect(transformConstraint({ $regex: '^a', $options: 'i' }, { type: 'String' }, 'name')).toEqual({
      $regex: '^a',
      $options: 'i',
    });
  });

  test('rejects a non-string $regex value', () => {
    expectParseError(
      () => transformConstraint({ $regex: /a/ }, { type: 'String' }, 'name'),
      Parse.Error.INVALID_JSON,
      /bad regex:/
    );
  });

  test('converts $containedBy into an $elemMatch/$nin expression', () => {
    expect(
      transformConstraint({ $containedBy: ['a', 'b'] }, { type: 'Array' }, 'tags')
    ).toEqual({
      $elemMatch: { $nin: ['a', 'b'] },
    });
  });

  test('rejects a non-array $containedBy value', () => {
    expectParseError(
      () => transformConstraint({ $containedBy: 'a' }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      'bad $containedBy: should be an array'
    );
  });

  test('accepts a uniform set of StartsWith regexes in $all', () => {
    const result = transformConstraint(
      { $all: [{ $regex: '^\\Qfoo\\E' }, { $regex: '^\\Qbar\\E' }] },
      { type: 'Array' },
      'tags'
    );
    expect(result.$all).toHaveLength(2);
    expect(result.$all[0]).toBeInstanceOf(RegExp);
    expect(result.$all[1]).toBeInstanceOf(RegExp);
    expect(result.$all[0].toString()).toBe('/^\\Qfoo\\E/');
    expect(result.$all[1].toString()).toBe('/^\\Qbar\\E/');
  });

  test('rejects a mixture of regex and non-regex values in $all', () => {
    expectParseError(
      () => transformConstraint({ $all: [{ $regex: '^\\Qfoo\\E' }, 'plain'] }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      /All \$all values must be of regex type or none/
    );
  });

  test('rejects a non-array $all value', () => {
    expectParseError(
      () => transformConstraint({ $all: 'a' }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      'bad $all value'
    );
  });

  test('translates full text search options', () => {
    expect(
      transformConstraint(
        {
          $text: {
            $search: {
              $term: 'space station',
              $language: 'en',
              $caseSensitive: true,
              $diacriticSensitive: false,
            },
          },
        },
        undefined,
        'name'
      )
    ).toEqual({
      $text: {
        $search: 'space station',
        $language: 'en',
        $caseSensitive: true,
      },
    });
  });

  test('validates $text options', () => {
    expectParseError(
      () => transformConstraint({ $text: { $search: 'not-an-object' } }, undefined, 'name'),
      Parse.Error.INVALID_JSON,
      'bad $text: $search, should be object'
    );
    expectParseError(
      () => transformConstraint({ $text: { $search: {} } }, undefined, 'name'),
      Parse.Error.INVALID_JSON,
      'bad $text: $term, should be string'
    );
    expectParseError(
      () => transformConstraint({ $text: { $search: { $term: 'x', $language: 4 } } }, undefined, 'name'),
      Parse.Error.INVALID_JSON,
      'bad $text: $language, should be string'
    );
  });

  test('translates $nearSphere normally', () => {
    expect(
      transformConstraint(
        { $nearSphere: { longitude: 10, latitude: 20 }, $maxDistance: 5 },
        undefined,
        'location'
      )
    ).toEqual({
      $nearSphere: [10, 20],
      $maxDistance: 5,
    });
  });

  test('translates $nearSphere to $geoWithin for count queries', () => {
    expect(
      transformConstraint(
        { $nearSphere: { longitude: 10, latitude: 20 }, $maxDistance: 5 },
        undefined,
        'location',
        true
      )
    ).toEqual({
      $geoWithin: { $centerSphere: [[10, 20], 5] },
    });
  });

  test('translates alternative distance units to radians', () => {
    expect(transformConstraint({ $maxDistanceInRadians: 2 }, undefined, 'location')).toEqual({
      $maxDistance: 2,
    });
    expect(transformConstraint({ $maxDistanceInMiles: 3959 }, undefined, 'location')).toEqual({
      $maxDistance: 1,
    });
    expect(transformConstraint({ $maxDistanceInKilometers: 6371 }, undefined, 'location')).toEqual({
      $maxDistance: 1,
    });
  });

  test('converts a $within box from GeoPoint order to longitude/latitude order', () => {
    expect(
      transformConstraint(
        {
          $within: {
            $box: [
              { longitude: 1, latitude: 2 },
              { longitude: 3, latitude: 4 },
            ],
          },
        },
        undefined,
        'location'
      )
    ).toEqual({ $within: { $box: [[1, 2], [3, 4]] } });
  });

  test('rejects malformed $within boxes', () => {
    expectParseError(
      () => transformConstraint({ $within: { $box: [{ longitude: 1, latitude: 2 }] } }, undefined, 'location'),
      Parse.Error.INVALID_JSON,
      'malformatted $within arg'
    );
  });

  test('converts $geoWithin polygons of GeoPoints', () => {
    expect(
      transformConstraint(
        {
          $geoWithin: {
            $polygon: [
              { __type: 'GeoPoint', longitude: 10, latitude: 20 },
              { __type: 'GeoPoint', longitude: 30, latitude: 40 },
              { __type: 'GeoPoint', longitude: 50, latitude: 60 },
            ],
          },
        },
        undefined,
        'location'
      )
    ).toEqual({ $geoWithin: { $polygon: [[10, 20], [30, 40], [50, 60]] } });
  });

  test('converts $geoWithin centerSphere expressions', () => {
    expect(
      transformConstraint(
        {
          $geoWithin: {
            $centerSphere: [{ __type: 'GeoPoint', longitude: 10, latitude: 20 }, 2.5],
          },
        },
        undefined,
        'location'
      )
    ).toEqual({ $geoWithin: { $centerSphere: [[10, 20], 2.5] } });
  });

  test('validates $geoWithin polygons and centerSphere distances', () => {
    expectParseError(
      () =>
        transformConstraint(
          {
            $geoWithin: {
              $polygon: [
                { __type: 'GeoPoint', longitude: 1, latitude: 2 },
                { __type: 'GeoPoint', longitude: 3, latitude: 4 },
              ],
            },
          },
          undefined,
          'location'
        ),
      Parse.Error.INVALID_JSON,
      'bad $geoWithin value; $polygon should contain at least 3 GeoPoints'
    );

    expectParseError(
      () =>
        transformConstraint(
          {
            $geoWithin: {
              $centerSphere: [{ __type: 'GeoPoint', longitude: 1, latitude: 2 }, -1],
            },
          },
          undefined,
          'location'
        ),
      Parse.Error.INVALID_JSON,
      'bad $geoWithin value; $centerSphere distance invalid'
    );
  });

  test('converts $geoIntersects points to GeoJSON', () => {
    expect(
      transformConstraint(
        {
          $geoIntersects: {
            $point: { __type: 'GeoPoint', longitude: 10, latitude: 20 },
          },
        },
        undefined,
        'location'
      )
    ).toEqual({
      $geoIntersects: { $geometry: { type: 'Point', coordinates: [10, 20] } },
    });
  });

  test('rejects unsupported select constraints and unknown $ constraints', () => {
    expectParseError(
      () => transformConstraint({ $select: {} }, undefined, 'owner'),
      Parse.Error.COMMAND_UNAVAILABLE,
      'the $select constraint is not supported yet'
    );
    expectParseError(
      () => transformConstraint({ $dontSelect: {} }, undefined, 'owner'),
      Parse.Error.COMMAND_UNAVAILABLE,
      'the $dontSelect constraint is not supported yet'
    );
    expectParseError(
      () => transformConstraint({ $unknown: 1 }, undefined, 'field'),
      Parse.Error.INVALID_JSON,
      'bad constraint: $unknown'
    );
  });

  test('returns CannotTransform-like value for non-constraint objects', () => {
    // The helper's sentinel is not exported, so observe the conversion through
    // an exported caller: a plain equality atom is handled by transformWhere.
    expect(transformWhere('Game', { name: 'alice' }, schemaWith({ name: { type: 'String' } }))).toEqual({
      name: 'alice',
    });
  });

  test('evaluates relative dates against the current time for $gt/$gte', () => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
    try {
      expect(
        transformConstraint(
          {
            $gt: { $relativeTime: 'in 2 days' },
            $lte: { $relativeTime: '3 hours ago' },
          },
          { type: 'Date' },
          'when'
        )
      ).toEqual({
        $gt: new Date('2024-01-03T00:00:00.000Z'),
        $lte: new Date('2023-12-31T21:00:00.000Z'),
      });
    } finally {
      jest.useRealTimers();
    }
  });

  test('validates relative-time fields, operators, and expressions', () => {
    expectParseError(
      () =>
        transformConstraint(
          { $gt: { $relativeTime: 'in 1 day' } },
          { type: 'String' },
          'field'
        ),
      Parse.Error.INVALID_JSON,
      '$relativeTime can only be used with Date field'
    );

    expectParseError(
      () =>
        transformConstraint(
          { $eq: { $relativeTime: 'in 1 day' } },
          { type: 'Date' },
          'when'
        ),
      Parse.Error.INVALID_JSON,
      '$relativeTime can only be used with the $lt, $lte, $gt, and $gte operators'
    );

    expectParseError(
      () =>
        transformConstraint(
          { $gt: { $relativeTime: 'tomorrow' } },
          { type: 'Date' },
          'when'
        ),
      Parse.Error.INVALID_JSON,
      /bad \$relativeTime \(\$gt\) value/
    );
  });
});

describe('parseObjectToMongoObjectForCreate', () => {
  const schema = schemaWith({
    owner: { type: 'Pointer', targetClass: '_User' },
    score: { type: 'Number' },
    tags: { type: 'Array' },
    profile: { type: 'Object' },
    friend: { type: 'Relation', targetClass: '_User' },
  });

  test('creates a Mongo object from ordinary fields and built-ins', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        '_User',
        {
          objectId: 'user-1',
          username: 'alice',
          sessionToken: 'sess',
          score: 12,
          _failed_login_count: 2,
          _hashed_password: 'hash',
        },
        schema
      )
    ).toEqual({
      _id: 'user-1',
      username: 'alice',
      _session_token: 'sess',
      score: 12,
      _failed_login_count: 2,
      _hashed_password: 'hash',
    });
  });

  test('uses legacy Mongo names for createdAt and updatedAt', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        'Game',
        {
          createdAt: '2024-01-02T03:04:05.678Z',
          updatedAt: { __type: 'Date', iso: '2024-02-03T04:05:06.789Z' },
        },
        schema
      )
    ).toEqual({
      _created_at: new Date('2024-01-02T03:04:05.678Z'),
      _updated_at: new Date('2024-02-03T04:05:06.789Z'),
    });
  });

  test('coerces auth expiration fields to dates', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        '_User',
        {
          expiresAt: '2024-05-01T00:00:00.000Z',
          _email_verify_token_expires_at: { __type: 'Date', iso: '2024-05-02T00:00:00.000Z' },
          _account_lockout_expires_at: '2024-05-03T00:00:00.000Z',
          _perishable_token_expires_at: '2024-05-04T00:00:00.000Z',
          _password_changed_at: '2024-05-05T00:00:00.000Z',
        },
        schema
      )
    ).toEqual({
      expiresAt: new Date('2024-05-01T00:00:00.000Z'),
      _email_verify_token_expires_at: new Date('2024-05-02T00:00:00.000Z'),
      _account_lockout_expires_at: new Date('2024-05-03T00:00:00.000Z'),
      _perishable_token_expires_at: new Date('2024-05-04T00:00:00.000Z'),
      _password_changed_at: new Date('2024-05-05T00:00:00.000Z'),
    });
  });

  test('prefixes pointer values and recursively transforms arrays and nested objects', () => {
    const iso = '2024-03-04T05:06:07.890Z';
    const result = parseObjectToMongoObjectForCreate(
      'Game',
      {
        owner: { __type: 'Pointer', className: '_User', objectId: 'u-1', extra: 'discarded' },
        tags: ['a', { __type: 'Date', iso }],
        profile: {
          friend: { __type: 'Pointer', className: '_User', objectId: 'u-2', extra: 'discarded' },
          nested: { value: 7 },
        },
      },
      schema
    );

    expect(result).toEqual({
      _p_owner: '_User$u-1',
      tags: ['a', new Date(iso)],
      profile: {
        friend: { __type: 'Pointer', className: '_User', objectId: 'u-2' },
        nested: { value: 7 },
      },
    });
  });

  test('converts REST value coders while creating objects', () => {
    const result = parseObjectToMongoObjectForCreate(
      'Game',
      {
        when: { __type: 'Date', iso: '2024-01-01T00:00:00.000Z' },
        data: { __type: 'Bytes', base64: 'aGVsbG8=' },
        location: { __type: 'GeoPoint', latitude: 20, longitude: 10 },
        shape: {
          __type: 'Polygon',
          coordinates: [
            [10, 20],
            [30, 40],
            [50, 60],
          ],
        },
        attachment: { __type: 'File', name: 'hello.txt' },
      },
      schema
    );

    expect(result.when).toEqual(new Date('2024-01-01T00:00:00.000Z'));
    expect(result.data).toBeInstanceOf(mongodb.Binary);
    expect(result.data.buffer.toString('base64')).toBe('aGVsbG8=');
    expect(result.location).toEqual([10, 20]);
    expect(result.shape).toEqual({
      type: 'Polygon',
      coordinates: [[[20, 10], [40, 30], [60, 50], [20, 10]]],
    });
    expect(result.attachment).toBe('hello.txt');
  });

  test('adds the legacy ACL representation without mutating the input', () => {
    const rest = { _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] };
    expect(parseObjectToMongoObjectForCreate('Game', rest, schema)).toEqual({
      _wperm: ['role:admin', 'user-1'],
      _rperm: ['user-1', '*'],
      _acl: {
        'role:admin': { w: true },
        'user-1': { w: true, r: true },
        '*': { r: true },
      },
    });
    expect(rest).toEqual({ _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] });
  });

  test('skips relations and undefined values', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        'Game',
        {
          friend: { __type: 'Relation', className: '_User' },
          name: undefined,
          score: 0,
        },
        schema
      )
    ).toEqual({ score: 0 });
  });

  test('rejects nested keys containing $ or .', () => {
    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          'Game',
          { profile: { 'bad.key': 1 } },
          schema
        ),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );

    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          'Game',
          { profile: { '$bad': 1 } },
          schema
        ),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );
  });

  test('rejects an untransformed ACL field', () => {
    expect(() =>
      parseObjectToMongoObjectForCreate('Game', { ACL: { 'user-1': { read: true } } }, schema)
    ).toThrow('There was a problem transforming an ACL.');
  });

  test('rejects authData subfields that should have been converted already', () => {
    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          '_User',
          { 'authData.facebook.id': 'fb-1' },
          schema
        ),
      Parse.Error.INVALID_KEY_NAME,
      'can only query on authData.facebook.id'
    );
  });

  test('trusts already transformed authData keys', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        '_User',
        { _auth_data_facebook: { id: 'fb-1' } },
        schema
      )
    ).toEqual({ _auth_data_facebook: { id: 'fb-1' } });
  });

  test('does not prefix Bytes fields as pointers even when the schema says Pointer', () => {
    const pointerSchema = schemaWith({ data: { type: 'Pointer', targetClass: '_User' } });
    const result = parseObjectToMongoObjectForCreate(
      'Game',
      { data: { __type: 'Bytes', base64: 'aGVsbG8=' } },
      pointerSchema
    );
    expect(result.data).toBeInstanceOf(mongodb.Binary);
    expect(result._p_data).toBeUndefined();
  });
});

describe('transformUpdate', () => {
  const schema = schemaWith({
    owner: { type: 'Pointer', targetClass: '_User' },
    score: { type: 'Number' },
    profile: { type: 'Object' },
    tags: { type: 'Array' },
    friend: { type: 'Relation', targetClass: '_User' },
  });

  test('builds a $set update for ordinary values and built-in fields', () => {
    expect(
      transformUpdate(
        'Game',
        {
          name: 'New name',
          objectId: 'game-1',
          sessionToken: 'sess',
          _failed_login_count: 4,
        },
        schema
      )
    ).toEqual({
      $set: {
        name: 'New name',
        _id: 'game-1',
        _session_token: 'sess',
        _failed_login_count: 4,
      },
    });
  });

  test('adds both modern and legacy ACL fields', () => {
    expect(
      transformUpdate('Game', { _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] }, schema)
    ).toEqual({
      $set: {
        _wperm: ['role:admin', 'user-1'],
        _rperm: ['user-1', '*'],
        _acl: {
          'role:admin': { w: true },
          'user-1': { w: true, r: true },
          '*': { r: true },
        },
      },
    });
  });

  test('prefixes pointers and leaves pointers inside nested documents unprefixed', () => {
    const result = transformUpdate(
      'Game',
      {
        owner: { __type: 'Pointer', className: '_User', objectId: 'u-1', extra: 'discarded' },
        profile: {
          friend: { __type: 'Pointer', className: '_User', objectId: 'u-2', extra: 'discarded' },
        },
      },
      schema
    );

    expect(result.$set._p_owner).toBe('_User$u-1');
    expect(result.$set.profile).toEqual({
      friend: { __type: 'Pointer', className: '_User', objectId: 'u-2' },
    });
  });

  test('coerces date-bearing update fields from strings', () => {
    const date = '2024-07-08T09:10:11.000Z';
    expect(
      transformUpdate(
        '_User',
        {
          createdAt: date,
          updatedAt: date,
          expiresAt: date,
          _email_verify_token_expires_at: date,
          _account_lockout_expires_at: date,
          _perishable_token_expires_at: date,
          _password_changed_at: date,
          lastUsed: date,
        },
        schema
      )
    ).toEqual({
      $set: {
        _created_at: new Date(date),
        _updated_at: new Date(date),
        expiresAt: new Date(date),
        _email_verify_token_expires_at: new Date(date),
        _account_lockout_expires_at: new Date(date),
        _perishable_token_expires_at: new Date(date),
        _password_changed_at: new Date(date),
        _last_used: new Date(date),
      },
    });
  });

  test('maps timesUsed and coerces GlobalConfig objectIds', () => {
    expect(transformUpdate('Game', { timesUsed: 5 }, schema)).toEqual({
      $set: { times_used: 5 },
    });
    expect(transformUpdate('_GlobalConfig', { objectId: '12' }, schemaWith({}))).toEqual({
      $set: { objectId: 12 },
    });
  });

  test('lifts update operators to the top level', () => {
    const iso = '2024-08-09T10:11:12.000Z';
    expect(
      transformUpdate(
        'Game',
        {
          score: { __op: 'Increment', amount: 2 },
          tags: { __op: 'Add', objects: ['a', { __type: 'Date', iso }] },
          uniqueTags: { __op: 'AddUnique', objects: ['b'] },
          removedTags: { __op: 'Remove', objects: ['c'] },
          obsolete: { __op: 'Delete' },
          createdOnInsert: { __op: 'SetOnInsert', amount: 'first' },
        },
        schema
      )
    ).toEqual({
      $inc: { score: 2 },
      $push: { tags: { $each: ['a', new Date(iso)] } },
      $addToSet: { uniqueTags: { $each: ['b'] } },
      $pullAll: { removedTags: ['c'] },
      $unset: { obsolete: '' },
      $setOnInsert: { createdOnInsert: 'first' },
    });
  });

  test('recursively preserves operators inside nested documents', () => {
    const profile = {
      views: { __op: 'Increment', amount: 1 },
      tags: { __op: 'Add', objects: ['x'] },
      gone: { __op: 'Delete' },
      removed: { __op: 'Remove', objects: ['y'] },
    };
    const result = transformUpdate('Game', { profile }, schema);

    // Nested values are data, not top-level update operators. They remain
    // embedded in the document instead of being lifted onto the update.
    expect(result).toEqual({ $set: { profile } });
  });

  test('skips relation values and preserves dotted field names', () => {
    expect(
      transformUpdate(
        'Game',
        {
          friend: { __type: 'Relation', className: '_User' },
          'profile.name': 'Ace',
        },
        schema
      )
    ).toEqual({
      $set: { 'profile.name': 'Ace' },
    });
  });

  test('rejects invalid nested keys in an update', () => {
    expectParseError(
      () => transformUpdate('Game', { profile: { nested: { 'bad.key': 1 } } }, schema),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );
  });

  test('validates update operator arguments', () => {
    expectParseError(
      () => transformUpdate('Game', { score: { __op: 'Increment', amount: '2' } }, schema),
      Parse.Error.INVALID_JSON,
      'incrementing must provide a number'
    );
    expectParseError(
      () => transformUpdate('Game', { tags: { __op: 'Add', objects: 'x' } }, schema),
      Parse.Error.INVALID_JSON,
      'objects to add must be an array'
    );
    expectParseError(
      () => transformUpdate('Game', { tags: { __op: 'Remove', objects: 'x' } }, schema),
      Parse.Error.INVALID_JSON,
      'objects to remove must be an array'
    );
  });

  test('rejects unsupported update operators', () => {
    expectParseError(
      () => transformUpdate('Game', { score: { __op: 'Multiply', amount: 2 } }, schema),
      Parse.Error.COMMAND_UNAVAILABLE,
      'The Multiply operator is not supported yet.'
    );
  });

  test('rejects function atoms', () => {
    expectParseError(
      () => transformUpdate('Game', { callback: function noop() {} }, schema),
      Parse.Error.INVALID_JSON,
      /cannot transform value/
    );
  });
});

describe('mongoObjectToParseObject', () => {
  const schema = schemaWith({
    name: { type: 'String' },
    age: { type: 'Number' },
    owner: { type: 'Pointer', targetClass: '_User' },
    notAPointer: { type: 'String' },
    avatar: { type: 'File' },
    location: { type: 'GeoPoint' },
    area: { type: 'Polygon' },
    data: { type: 'Bytes' },
    tags: { type: 'Array' },
  });

  test('passes primitive values through unchanged', () => {
    expect(mongoObjectToParseObject('Game', 'text', schema)).toBe('text');
    expect(mongoObjectToParseObject('Game', 42, schema)).toBe(42);
    expect(mongoObjectToParseObject('Game', true, schema)).toBe(true);
    expect(mongoObjectToParseObject('Game', null, schema)).toBeNull();
    expect(mongoObjectToParseObject('Game', undefined, schema)).toBeUndefined();
  });

  test('maps Mongo scalar wrappers and binary data', () => {
    expect(mongoObjectToParseObject('Game', mongodb.Long.fromNumber(42), schema)).toBe(42);
    expect(mongoObjectToParseObject('Game', new mongodb.Double(1.5), schema)).toBe(1.5);
    expect(
      mongoObjectToParseObject('Game', new mongodb.Binary(Buffer.from('hello')), schema)
    ).toEqual({ __type: 'Bytes', base64: 'aGVsbG8=' });
  });

  test('maps the standard Mongo row fields to Parse representation', () => {
    const created = new Date('2024-01-02T03:04:05.678Z');
    const updated = new Date('2024-02-03T04:05:06.789Z');
    const lastUsed = new Date('2024-03-04T05:06:07.890Z');

    expect(
      mongoObjectToParseObject(
        '_User',
        {
          _id: 'user-1',
          name: 'Alice',
          age: 30,
          _hashed_password: 'hash',
          _session_token: 'token',
          _created_at: created,
          _updated_at: updated,
          lastUsed,
          timesUsed: 7,
          _failed_login_count: 2,
          _timestamps: { ignored: true },
        },
        schema
      )
    ).toEqual({
      objectId: 'user-1',
      name: 'Alice',
      age: 30,
      _hashed_password: 'hash',
      sessionToken: 'token',
      createdAt: created.toISOString(),
      updatedAt: updated.toISOString(),
      lastUsed: lastUsed.toISOString(),
      timesUsed: 7,
      _failed_login_count: 2,
    });
  });

  test('maps expiration and token fields and drops the stored ACL', () => {
    const result = mongoObjectToParseObject(
      '_User',
      {
        _email_verify_token: 'verify',
        _perishable_token: 'perishable',
        _perishable_token_expires_at: 'raw-expiry',
        _password_changed_at: 'raw-changed',
        _tombstone: true,
        _email_verify_token_expires_at: 'raw-email-expiry',
        _account_lockout_expires_at: 'raw-lockout-expiry',
        _password_history: [{ password: 'old' }],
        expiresAt: new Date('2024-04-05T06:07:08.000Z'),
        _acl: { 'user-1': { r: true } },
      },
      schema
    );

    expect(result).toMatchObject({
      _email_verify_token: 'verify',
      _perishable_token: 'perishable',
      _perishable_token_expires_at: 'raw-expiry',
      _password_changed_at: 'raw-changed',
      _tombstone: true,
      _email_verify_token_expires_at: 'raw-email-expiry',
      _account_lockout_expires_at: 'raw-lockout-expiry',
      _password_history: [{ password: 'old' }],
      expiresAt: { __type: 'Date', iso: '2024-04-05T06:07:08.000Z' },
    });
    expect(result._acl).toBeUndefined();
  });

  test('synthesizes and filters authData for _User rows', () => {
    expect(
      mongoObjectToParseObject(
        '_User',
        {
          _auth_data_facebook: { id: 'fb-1' },
          _auth_data_google: { id: 'g-1' },
          authData: { should: 'be ignored' },
        },
        schema
      )
    ).toEqual({
      authData: {
        facebook: { id: 'fb-1' },
        google: { id: 'g-1' },
      },
    });
  });

  test('keeps authData for non-user classes', () => {
    expect(
      mongoObjectToParseObject(
        'Game',
        {
          authData: { custom: true },
          _auth_data_facebook: { id: 'should-drop' },
        },
        schema
      )
    ).toEqual({ authData: { custom: true } });
  });

  test('resolves pointers and drops missing, non-pointer, and null pointer columns', () => {
    expect(
      mongoObjectToParseObject(
        'Game',
        {
          _p_owner: '_User$u-1',
          _p_missing: '_User$u-2',
          _p_notAPointer: '_User$u-3',
          _p_nullPointer: null,
        },
        {
          fields: {
            owner: { type: 'Pointer', targetClass: '_User' },
            notAPointer: { type: 'String' },
            nullPointer: { type: 'Pointer', targetClass: '_User' },
          },
        }
      )
    ).toEqual({
      owner: { __type: 'Pointer', className: '_User', objectId: 'u-1' },
    });
  });

  test('rejects pointer strings with the wrong target class', () => {
    expect(() =>
      mongoObjectToParseObject('Game', { _p_owner: 'Game$g-1' }, schema)
    ).toThrow('pointer to incorrect className');
  });

  test('converts File, GeoPoint, Polygon, and Bytes database values', () => {
    const result = mongoObjectToParseObject(
      'Game',
      {
        avatar: 'avatar.png',
        location: [10, 20],
        area: {
          type: 'Polygon',
          coordinates: [
            [
              [10, 20],
              [30, 40],
              [50, 60],
              [10, 20],
            ],
          ],
        },
        data: new mongodb.Binary(Buffer.from('hello')),
        tags: ['one', 'two'],
      },
      schema
    );

    expect(result).toEqual({
      avatar: { __type: 'File', name: 'avatar.png' },
      location: { __type: 'GeoPoint', latitude: 20, longitude: 10 },
      area: {
        __type: 'Polygon',
        coordinates: [
          [20, 10],
          [40, 30],
          [60, 50],
          [20, 10],
        ],
      },
      data: { __type: 'Bytes', base64: 'aGVsbG8=' },
      tags: ['one', 'two'],
    });
  });

  test('converts nested dates and Mongo values recursively', () => {
    const date = new Date('2024-06-07T08:09:10.000Z');
    expect(
      mongoObjectToParseObject(
        'Game',
        {
          profile: {
            joined: date,
            count: mongodb.Long.fromNumber(3),
            values: [date, { count: mongodb.Long.fromNumber(4) }],
          },
        },
        schema
      )
    ).toEqual({
      profile: {
        joined: { __type: 'Date', iso: date.toISOString() },
        count: 3,
        values: [{ __type: 'Date', iso: date.toISOString() }, { count: 4 }],
      },
    });
  });

  test('synthesizes relation fields declared in schema', () => {
    const relationSchema = schemaWith({
      name: { type: 'String' },
      friend: { type: 'Relation', targetClass: '_User' },
    });
    expect(mongoObjectToParseObject('Game', { name: 'Chess' }, relationSchema)).toEqual({
      name: 'Chess',
      friend: { __type: 'Relation', className: '_User' },
    });
  });

  test('drops unrecognized reserved keys', () => {
    expect(
      mongoObjectToParseObject('Game', { name: 'Chess', _mystery: 'do not expose' }, schema)
    ).toEqual({
      name: 'Chess',
    });
  });

  test('does not mutate the input when legacy permissions are present', () => {
    const mongoObject = { _rperm: ['user-1'], _wperm: ['role:admin'], name: 'Chess' };
    const result = mongoObjectToParseObject('Game', mongoObject, schema);

    expect(result._rperm).toEqual(['user-1']);
    expect(result._wperm).toEqual(['role:admin']);
    expect(mongoObject).not.toHaveProperty('_rperm');
    expect(mongoObject).not.toHaveProperty('_wperm');
  });

  test('rejects functions and symbols', () => {
    expect(() => mongoObjectToParseObject('Game', function noop() {}, schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
    expect(() => mongoObjectToParseObject('Game', Symbol('bad'), schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
  });
});
